// HYLE's Vulkan adapter treats resource exhaustion as a recoverable value.
// Validate before padding; external arena ownership stays with the caller.
if (params.mem_size > SIZE_MAX - (GGML_MEM_ALIGN - 1) ||
    (params.mem_buffer != NULL && (uintptr_t) params.mem_buffer % GGML_MEM_ALIGN != 0)) {
    return NULL;
}
struct ggml_context * ctx = malloc(sizeof(struct ggml_context));
if (ctx == NULL) {
    return NULL;
}
